FROM (SELECT t.*, (NOT ((c3_s = 0 AND NOT c3_b) OR (c5_s = 0 AND NOT c5_b))) AS c6_b, rede_div_n(c11_n, c11_d, CAST(1000000 AS BIGINT), CAST(1 AS BIGINT)) AS c12_n, rede_div_d(c11_n, c11_d, CAST(1000000 AS BIGINT), CAST(1 AS BIGINT)) AS c12_d, rede_div_n(c15_n, c15_d, CAST(1000000 AS BIGINT), CAST(1 AS BIGINT)) AS c16_n, rede_div_d(c15_n, c15_d, CAST(1000000 AS BIGINT), CAST(1 AS BIGINT)) AS c16_d
FROM (SELECT t.*, CASE WHEN GREATEST(c0_s, c1_s) > 0 THEN GREATEST(c0_s, c1_s) ELSE 0 END AS c2_s, CASE WHEN GREATEST(c0_s, c1_s) > 0 THEN CASE WHEN c0_s = GREATEST(c0_s, c1_s) THEN c0_r WHEN c1_s = GREATEST(c0_s, c1_s) THEN c1_r ELSE '' END ELSE '' END AS c2_r, CASE WHEN GREATEST(c1_s, c0_s) > 0 THEN GREATEST(c1_s, c0_s) ELSE 0 END AS c3_s, CASE WHEN GREATEST(c1_s, c0_s) > 0 THEN CASE WHEN c1_s = GREATEST(c1_s, c0_s) THEN c1_r WHEN c0_s = GREATEST(c1_s, c0_s) THEN c0_r ELSE '' END ELSE '' END AS c3_r, CASE WHEN GREATEST(c0_s, c4_s) > 0 THEN GREATEST(c0_s, c4_s) ELSE 0 END AS c5_s, CASE WHEN GREATEST(c0_s, c4_s) > 0 THEN CASE WHEN c0_s = GREATEST(c0_s, c4_s) THEN c0_r WHEN c4_s = GREATEST(c0_s, c4_s) THEN c4_r ELSE '' END ELSE '' END AS c5_r, CASE WHEN GREATEST(c4_s, c0_s) > 0 THEN GREATEST(c4_s, c0_s) ELSE 0 END AS c7_s, CASE WHEN GREATEST(c4_s, c0_s) > 0 THEN CASE WHEN c4_s = GREATEST(c4_s, c0_s) THEN c4_r WHEN c0_s = GREATEST(c4_s, c0_s) THEN c0_r ELSE '' END ELSE '' END AS c7_r
FROM (SELECT t.*, (rede_cmp(c0_n, CAST(1 AS BIGINT), c1_n, c1_d) <= 0) AS c2_b, (rede_cmp(c1_n, c1_d, c0_n, CAST(1 AS BIGINT)) < 0) AS c3_b, (rede_cmp(c0_n, CAST(1 AS BIGINT), c4_n, c4_d) <= 0) AS c5_b, (rede_cmp(c4_n, c4_d, c0_n, CAST(1 AS BIGINT)) < 0) AS c7_b, rede_mul_n(c8_n, CAST(1 AS BIGINT), c9_n, CAST(1 AS BIGINT)) AS c11_n, rede_mul_d(c8_n, CAST(1 AS BIGINT), c9_n, CAST(1 AS BIGINT)) AS c11_d, rede_mul_n(c8_n, CAST(1 AS BIGINT), c14_n, CAST(1 AS BIGINT)) AS c15_n, rede_mul_d(c8_n, CAST(1 AS BIGINT), c14_n, CAST(1 AS BIGINT)) AS c15_d
FROM (SELECT s.id AS subject, COALESCE(j0.v, CAST(0 AS BIGINT)) AS c0_n, CASE WHEN j0.c IS NULL THEN 2 WHEN j0.c > 1 THEN 3 WHEN j0.v < -9223372036854775807 THEN 3 ELSE 0 END AS c0_s, CASE WHEN j0.c IS NULL THEN 'fact assessed_income.cents is missing' WHEN j0.c > 1 THEN 'fact assessed_income.cents has more than one value' WHEN j0.v < -9223372036854775807 THEN 'fact assessed_income.cents does not fit 64 bits' ELSE '' END AS c0_r, COALESCE(j1.n, CAST(0 AS BIGINT)) AS c1_n, COALESCE(j1.d, CAST(1 AS BIGINT)) AS c1_d, CASE j1.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c1_s, COALESCE(j1.reason, 'rule income_threshold has no value') AS c1_r, COALESCE(j2.n, CAST(0 AS BIGINT)) AS c4_n, COALESCE(j2.d, CAST(1 AS BIGINT)) AS c4_d, CASE j2.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c4_s, COALESCE(j2.reason, 'rule income_limit has no value') AS c4_r, COALESCE(j3.v, CAST(0 AS BIGINT)) AS c8_n, CASE WHEN j3.c IS NULL THEN 2 WHEN j3.c > 1 THEN 3 WHEN j3.v < -9223372036854775807 THEN 3 ELSE 0 END AS c8_s, CASE WHEN j3.c IS NULL THEN 'fact assessed_costs.cents is missing' WHEN j3.c > 1 THEN 'fact assessed_costs.cents has more than one value' WHEN j3.v < -9223372036854775807 THEN 'fact assessed_costs.cents does not fit 64 bits' ELSE '' END AS c8_r, COALESCE(j4.v, CAST(0 AS BIGINT)) AS c9_n, COALESCE(j4.e, '') AS c9_e, CASE WHEN j4.k IS NULL THEN 2 WHEN j4.k = 1 THEN 2 WHEN j4.k = 2 THEN 3 WHEN j4.k = 3 THEN 2 WHEN j4.k = 4 THEN 2 WHEN j4.k = 5 THEN 3 WHEN j4.v < -9223372036854775807 THEN 3 ELSE 0 END AS c9_s, CASE WHEN j4.k IS NULL THEN 'parameter full_rate is missing' WHEN j4.k = 1 THEN 'no evaluation date (as_of)' WHEN j4.k = 2 THEN 'more than one evaluation date (as_of)' WHEN j4.k = 3 THEN 'parameter full_rate has no row valid on the evaluation date' WHEN j4.k = 4 THEN 'parameter full_rate is not known on the evaluation date' WHEN j4.k = 5 THEN 'parameter full_rate has more than one value' WHEN j4.v < -9223372036854775807 THEN 'parameter full_rate does not fit 64 bits' ELSE '' END AS c9_r, COALESCE(j5.v, CAST(0 AS BIGINT)) AS c14_n, COALESCE(j5.e, '') AS c14_e, CASE WHEN j5.k IS NULL THEN 2 WHEN j5.k = 1 THEN 2 WHEN j5.k = 2 THEN 3 WHEN j5.k = 3 THEN 2 WHEN j5.k = 4 THEN 2 WHEN j5.k = 5 THEN 3 WHEN j5.v < -9223372036854775807 THEN 3 ELSE 0 END AS c14_s, CASE WHEN j5.k IS NULL THEN 'parameter partial_rate is missing' WHEN j5.k = 1 THEN 'no evaluation date (as_of)' WHEN j5.k = 2 THEN 'more than one evaluation date (as_of)' WHEN j5.k = 3 THEN 'parameter partial_rate has no row valid on the evaluation date' WHEN j5.k = 4 THEN 'parameter partial_rate is not known on the evaluation date' WHEN j5.k = 5 THEN 'parameter partial_rate has more than one value' WHEN j5.v < -9223372036854775807 THEN 'parameter partial_rate does not fit 64 bits' ELSE '' END AS c14_r
FROM (SELECT DISTINCT id FROM "application") s
