LEFT JOIN "calc__income_threshold" j1 ON j1.subject = s.id
LEFT JOIN "calc__income_limit" j2 ON j2.subject = s.id
LEFT JOIN (SELECT "application" AS id, MIN("cents") AS v, COUNT(DISTINCT "cents") AS c FROM "assessed_costs" GROUP BY "application") j3 ON j3.id = s.id
LEFT JOIN "calc__parameter" j4 ON j4.name = 'full_rate'
LEFT JOIN "calc__parameter" j5 ON j5.name = 'partial_rate') t) t) t) t) t) t) t) t;
CREATE OR REPLACE TABLE "calc__cost_share__2026" AS
