FROM (SELECT s.id AS subject, (j0.id IS NOT NULL) AS c1_b, COALESCE(j1.n, CAST(0 AS BIGINT)) AS c3_n, COALESCE(j1.d, CAST(1 AS BIGINT)) AS c3_d, CASE j1.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c3_s, COALESCE(j1.reason, 'rule cost_share has no value') AS c3_r, COALESCE(j2.v, CAST(0 AS BIGINT)) AS c6_n, COALESCE(j2.e, '') AS c6_e, CASE WHEN j2.k IS NULL THEN 2 WHEN j2.k = 1 THEN 2 WHEN j2.k = 2 THEN 3 WHEN j2.k = 3 THEN 2 WHEN j2.k = 4 THEN 2 WHEN j2.k = 5 THEN 3 WHEN j2.v < -9223372036854775807 THEN 3 ELSE 0 END AS c6_s, CASE WHEN j2.k IS NULL THEN 'parameter advice_allowance is missing' WHEN j2.k = 1 THEN 'no evaluation date (as_of)' WHEN j2.k = 2 THEN 'more than one evaluation date (as_of)' WHEN j2.k = 3 THEN 'parameter advice_allowance has no row valid on the evaluation date' WHEN j2.k = 4 THEN 'parameter advice_allowance is not known on the evaluation date' WHEN j2.k = 5 THEN 'parameter advice_allowance has more than one value' WHEN j2.v < -9223372036854775807 THEN 'parameter advice_allowance does not fit 64 bits' ELSE '' END AS c6_r
FROM (SELECT DISTINCT id FROM "application") s
