FROM (SELECT s.id AS subject, COALESCE(j0.n, CAST(0 AS BIGINT)) AS c1_n, COALESCE(j0.d, CAST(1 AS BIGINT)) AS c1_d, CASE j0.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c1_s, COALESCE(j0.reason, 'rule cost_share has no value') AS c1_r, COALESCE(j1.n, CAST(0 AS BIGINT)) AS c2_n, COALESCE(j1.d, CAST(1 AS BIGINT)) AS c2_d, CASE j1.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c2_s, COALESCE(j1.reason, 'rule advice_allowance has no value') AS c2_r
FROM (SELECT DISTINCT id FROM "application") s
LEFT JOIN "calc__cost_share" j0 ON j0.subject = s.id
LEFT JOIN "calc__advice_allowance" j1 ON j1.subject = s.id) t) t) t) t;
CREATE OR REPLACE TABLE "calc__entitlement__2026" AS
