FROM (SELECT s.id AS subject, CASE WHEN a.c IS NULL THEN -1 WHEN a.c > 2 THEN -2 WHEN NOT ((a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01')) THEN -3 WHEN a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01' AND a.known_at >= DATE '2025-12-09' THEN 1 ELSE -4 END AS sel
