CREATE OR REPLACE TABLE "calc__award__2026__witness" AS
SELECT t.subject, t.pick, t.state, t.reason, c1_n AS c1_n, c1_d AS c1_d, c1_s AS c1_s, CAST(c1_r AS VARCHAR) AS c1_r, c2_n AS c2_n, CAST(1 AS BIGINT) AS c2_d, CAST(c2_e AS VARCHAR) AS c2_e, c2_s AS c2_s, CAST(c2_r AS VARCHAR) AS c2_r, c3_n AS c3_n, c3_d AS c3_d, c3_s AS c3_s, CAST(c3_r AS VARCHAR) AS c3_r
FROM (SELECT t.*, CASE WHEN (0 = 0 AND TRUE) THEN 1 ELSE 0 END AS pick, CASE WHEN (0 = 0 AND TRUE) THEN c3_s ELSE 1 END AS state, CASE WHEN (0 = 0 AND TRUE) THEN c3_r ELSE 'no definition of award@2026 applies' END AS reason
FROM (SELECT t.*, CASE WHEN GREATEST(c1_s, c2_s) > 0 THEN GREATEST(c1_s, c2_s) ELSE 0 END AS c3_s, CASE WHEN GREATEST(c1_s, c2_s) > 0 THEN CASE WHEN c1_s = GREATEST(c1_s, c2_s) THEN c1_r WHEN c2_s = GREATEST(c1_s, c2_s) THEN c2_r ELSE '' END ELSE '' END AS c3_r
FROM (SELECT t.*, CASE WHEN rede_cmp(c1_n, c1_d, c2_n, CAST(1 AS BIGINT)) <= 0 THEN c1_n ELSE c2_n END AS c3_n, CASE WHEN rede_cmp(c1_n, c1_d, c2_n, CAST(1 AS BIGINT)) <= 0 THEN c1_d ELSE CAST(1 AS BIGINT) END AS c3_d
FROM (SELECT s.id AS subject, COALESCE(j0.n, CAST(0 AS BIGINT)) AS c1_n, COALESCE(j0.d, CAST(1 AS BIGINT)) AS c1_d, CASE j0.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c1_s, COALESCE(j0.reason, 'rule entitlement has no value') AS c1_r, COALESCE(j1.v, CAST(0 AS BIGINT)) AS c2_n, COALESCE(j1.e, '') AS c2_e, CASE WHEN j1.k IS NULL THEN 2 WHEN j1.k = 1 THEN 2 WHEN j1.k = 2 THEN 3 WHEN j1.k = 3 THEN 2 WHEN j1.k = 4 THEN 2 WHEN j1.k = 5 THEN 3 WHEN j1.v < -9223372036854775807 THEN 3 ELSE 0 END AS c2_s, CASE WHEN j1.k IS NULL THEN 'parameter maximum_award is missing' WHEN j1.k = 1 THEN 'no evaluation date (as_of)' WHEN j1.k = 2 THEN 'more than one evaluation date (as_of)' WHEN j1.k = 3 THEN 'parameter maximum_award has no row valid on the evaluation date' WHEN j1.k = 4 THEN 'parameter maximum_award is not known on the evaluation date' WHEN j1.k = 5 THEN 'parameter maximum_award has more than one value' WHEN j1.v < -9223372036854775807 THEN 'parameter maximum_award does not fit 64 bits' ELSE '' END AS c2_r
FROM (SELECT DISTINCT id FROM "application") s
LEFT JOIN "calc__entitlement" j0 ON j0.subject = s.id
LEFT JOIN "calc__parameter" j1 ON j1.name = 'maximum_award') t) t) t) t;
CREATE OR REPLACE TABLE "calc__award__2026" AS
SELECT t.subject, CASE WHEN t.state = 0 THEN (CASE t.pick WHEN 1 THEN c3_n ELSE CAST(0 AS BIGINT) END) ELSE CAST(0 AS BIGINT) END AS n, CASE WHEN t.state = 0 THEN (CASE t.pick WHEN 1 THEN c3_d ELSE CAST(1 AS BIGINT) END) ELSE CAST(1 AS BIGINT) END AS d, FALSE AS b, CAST(CASE t.state WHEN 0 THEN 'known' WHEN 1 THEN 'not_applicable' WHEN 2 THEN 'unknown' ELSE 'invalid' END AS VARCHAR) AS state, CAST(t.reason AS VARCHAR) AS reason, CAST(CASE t.pick WHEN 1 THEN 'at_most_the_maximum' ELSE '' END AS VARCHAR) AS definition
FROM "calc__award__2026__witness" t;
CREATE OR REPLACE TABLE "calc__award" AS
SELECT t.subject, CASE t.sel WHEN 1 THEN COALESCE(v0.n, CAST(0 AS BIGINT)) ELSE CAST(0 AS BIGINT) END AS n, CASE t.sel WHEN 1 THEN COALESCE(v0.d, CAST(1 AS BIGINT)) ELSE CAST(1 AS BIGINT) END AS d, CASE t.sel WHEN 1 THEN COALESCE(v0.b, FALSE) ELSE FALSE END AS b, CAST(CASE t.sel WHEN -1 THEN 'unknown' WHEN -2 THEN 'invalid' WHEN -3 THEN 'not_applicable' WHEN -4 THEN 'unknown' WHEN 1 THEN COALESCE(v0.state, 'unknown') ELSE 'unknown' END AS VARCHAR) AS state, CAST(CASE t.sel WHEN -1 THEN 'no evaluation date (as_of)' WHEN -2 THEN 'more than one evaluation date (as_of)' WHEN -3 THEN 'no version of award is valid on the evaluation date' WHEN -4 THEN 'no version of award is known on the evaluation date' WHEN 1 THEN COALESCE(v0.reason, 'no value') ELSE 'no value' END AS VARCHAR) AS reason, CAST(CASE t.sel WHEN 1 THEN COALESCE(v0.definition, '') ELSE '' END AS VARCHAR) AS definition, CAST(CASE t.sel WHEN 1 THEN '2026' ELSE '' END AS VARCHAR) AS version
FROM (SELECT s.id AS subject, CASE WHEN a.c IS NULL THEN -1 WHEN a.c > 2 THEN -2 WHEN NOT ((a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01')) THEN -3 WHEN a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01' AND a.known_at >= DATE '2025-12-09' THEN 1 ELSE -4 END AS sel
FROM (SELECT DISTINCT id FROM "application") s
LEFT JOIN (SELECT id, MIN(valid_at) AS valid_at, MIN(known_at) AS known_at, COUNT(DISTINCT valid_at) + COUNT(DISTINCT known_at) AS c FROM "calc__as_of" GROUP BY id) a ON a.id = 'as_of') t
LEFT JOIN "calc__award__2026" v0 ON v0.subject = t.subject;
CREATE OR REPLACE TABLE "calc__payment_difference__2026__witness" AS
SELECT t.subject, t.pick, t.state, t.reason, c0_b AS c0_b, 0 AS c0_s, CAST('' AS VARCHAR) AS c0_r, c1_n AS c1_n, CAST(1 AS BIGINT) AS c1_d, c1_s AS c1_s, CAST(c1_r AS VARCHAR) AS c1_r, c2_n AS c2_n, c2_d AS c2_d, c2_s AS c2_s, CAST(c2_r AS VARCHAR) AS c2_r, c3_n AS c3_n, c3_d AS c3_d, c3_s AS c3_s, CAST(c3_r AS VARCHAR) AS c3_r
FROM (SELECT t.*, CASE WHEN (0 = 0 AND c0_b) THEN 1 ELSE 0 END AS pick, CASE WHEN (0 = 0 AND c0_b) THEN c3_s ELSE 1 END AS state, CASE WHEN (0 = 0 AND c0_b) THEN c3_r ELSE 'no definition of payment_difference@2026 applies' END AS reason
FROM (SELECT t.*, CASE WHEN GREATEST(c1_s, c2_s) > 0 THEN GREATEST(c1_s, c2_s) WHEN c3_d = 0 THEN 2 ELSE 0 END AS c3_s, CASE WHEN GREATEST(c1_s, c2_s) > 0 THEN CASE WHEN c1_s = GREATEST(c1_s, c2_s) THEN c1_r WHEN c2_s = GREATEST(c1_s, c2_s) THEN c2_r ELSE '' END WHEN c3_d = 0 THEN 'beyond the bound of W8 in sub' ELSE '' END AS c3_r
FROM (SELECT t.*, rede_sub_n(c1_n, CAST(1 AS BIGINT), c2_n, c2_d) AS c3_n, rede_sub_d(c1_n, CAST(1 AS BIGINT), c2_n, c2_d) AS c3_d
FROM (SELECT s.id AS subject, (j0.id IS NOT NULL) AS c0_b, COALESCE(j1.v, CAST(0 AS BIGINT)) AS c1_n, CASE WHEN j1.c IS NULL THEN 2 WHEN j1.c > 1 THEN 3 WHEN j1.v < -9223372036854775807 THEN 3 ELSE 0 END AS c1_s, CASE WHEN j1.c IS NULL THEN 'fact ledger_paid.cents is missing' WHEN j1.c > 1 THEN 'fact ledger_paid.cents has more than one value' WHEN j1.v < -9223372036854775807 THEN 'fact ledger_paid.cents does not fit 64 bits' ELSE '' END AS c1_r, COALESCE(j2.n, CAST(0 AS BIGINT)) AS c2_n, COALESCE(j2.d, CAST(1 AS BIGINT)) AS c2_d, CASE j2.state WHEN 'known' THEN 0 WHEN 'not_applicable' THEN 1 WHEN 'unknown' THEN 2 WHEN 'invalid' THEN 3 ELSE 2 END AS c2_s, COALESCE(j2.reason, 'rule award has no value') AS c2_r
FROM (SELECT DISTINCT id FROM "application") s
LEFT JOIN (SELECT DISTINCT "application" AS id FROM "paid") j0 ON j0.id = s.id
LEFT JOIN (SELECT "application" AS id, MIN("cents") AS v, COUNT(DISTINCT "cents") AS c FROM "ledger_paid" GROUP BY "application") j1 ON j1.id = s.id
LEFT JOIN "calc__award" j2 ON j2.subject = s.id) t) t) t) t;
CREATE OR REPLACE TABLE "calc__payment_difference__2026" AS
SELECT t.subject, CASE WHEN t.state = 0 THEN (CASE t.pick WHEN 1 THEN c3_n ELSE CAST(0 AS BIGINT) END) ELSE CAST(0 AS BIGINT) END AS n, CASE WHEN t.state = 0 THEN (CASE t.pick WHEN 1 THEN c3_d ELSE CAST(1 AS BIGINT) END) ELSE CAST(1 AS BIGINT) END AS d, FALSE AS b, CAST(CASE t.state WHEN 0 THEN 'known' WHEN 1 THEN 'not_applicable' WHEN 2 THEN 'unknown' ELSE 'invalid' END AS VARCHAR) AS state, CAST(t.reason AS VARCHAR) AS reason, CAST(CASE t.pick WHEN 1 THEN 'paid_minus_award' ELSE '' END AS VARCHAR) AS definition
FROM "calc__payment_difference__2026__witness" t;
CREATE OR REPLACE TABLE "calc__payment_difference" AS
SELECT t.subject, CASE t.sel WHEN 1 THEN COALESCE(v0.n, CAST(0 AS BIGINT)) ELSE CAST(0 AS BIGINT) END AS n, CASE t.sel WHEN 1 THEN COALESCE(v0.d, CAST(1 AS BIGINT)) ELSE CAST(1 AS BIGINT) END AS d, CASE t.sel WHEN 1 THEN COALESCE(v0.b, FALSE) ELSE FALSE END AS b, CAST(CASE t.sel WHEN -1 THEN 'unknown' WHEN -2 THEN 'invalid' WHEN -3 THEN 'not_applicable' WHEN -4 THEN 'unknown' WHEN 1 THEN COALESCE(v0.state, 'unknown') ELSE 'unknown' END AS VARCHAR) AS state, CAST(CASE t.sel WHEN -1 THEN 'no evaluation date (as_of)' WHEN -2 THEN 'more than one evaluation date (as_of)' WHEN -3 THEN 'no version of payment_difference is valid on the evaluation date' WHEN -4 THEN 'no version of payment_difference is known on the evaluation date' WHEN 1 THEN COALESCE(v0.reason, 'no value') ELSE 'no value' END AS VARCHAR) AS reason, CAST(CASE t.sel WHEN 1 THEN COALESCE(v0.definition, '') ELSE '' END AS VARCHAR) AS definition, CAST(CASE t.sel WHEN 1 THEN '2026' ELSE '' END AS VARCHAR) AS version
FROM (SELECT s.id AS subject, CASE WHEN a.c IS NULL THEN -1 WHEN a.c > 2 THEN -2 WHEN NOT ((a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01')) THEN -3 WHEN a.valid_at >= DATE '2026-01-01' AND a.valid_at < DATE '2027-01-01' AND a.known_at >= DATE '2025-12-09' THEN 1 ELSE -4 END AS sel
FROM (SELECT DISTINCT id FROM "application") s
LEFT JOIN (SELECT id, MIN(valid_at) AS valid_at, MIN(known_at) AS known_at, COUNT(DISTINCT valid_at) + COUNT(DISTINCT known_at) AS c FROM "calc__as_of" GROUP BY id) a ON a.id = 'as_of') t
LEFT JOIN "calc__payment_difference__2026" v0 ON v0.subject = t.subject;
